export const INITIAL_HIDDEN_SPOTS: HiddenSpot[] = RAW_SPOTS.map((spot) =>
  REAL_IMAGES[spot.id] ? { ...spot, imageUrl: REAL_IMAGES[spot.id] } : spot
);

